//! SPEC: canon §1.9 atan2_bam, doc 02 §4.4
//!
//! 16-iteration CORDIC in vectoring mode on `i64`. The angle accumulates in
//! units of 2^-16 Bam (one full turn is 2^32) using the committed table
//! [`ATAN_T`] generated by `tools/gen_trig.py`.

use crate::fx::Fx;
use crate::trig::{Bam, PITCH_LIMIT};

pub use crate::cordic_table::ATAN_T;

/// SPEC: canon §1.9, doc 02 §4.4. Number of CORDIC iterations.
pub const CORDIC_ITERS: usize = 16;

/// SPEC: canon §1.9 and doc 02 §4.4 `atan2_bam(y, x)`: the `Bam` angle of the
/// vector `(x, y)` measured counter-clockwise from +x, in `0..=65535`.
///
/// Exact on the axes (`(0, 0)` returns 0). Otherwise the vector is
/// normalized so `max(|x|, |y|)` lies in `[2^52, 2^53)`, pre-rotated into the
/// right half-plane, driven to `y = 0` by 16 vectoring iterations, and the
/// accumulated angle is rounded half up to whole Bam and wrapped. Accuracy
/// contract (doc 02 §4.4): `|error| <= 1 Bam` against the exact angle.
#[must_use]
pub fn atan2_bam(y: i64, x: i64) -> Bam {
    if y == 0 {
        return if x >= 0 { 0 } else { 32_768 };
    }
    if x == 0 {
        return if y > 0 { 16_384 } else { 49_152 };
    }
    // 1. Normalize so max(|x|, |y|) lies in [2^52, 2^53).
    let m = x.unsigned_abs().max(y.unsigned_abs());
    let s = i32::try_from(m.leading_zeros()).expect("0..=63") - 11;
    let shift = |v: i64| -> i64 {
        let w = i128::from(v);
        let w = if s >= 0 { w << s } else { w >> -s };
        i64::try_from(w).expect("atan2_bam: normalized value fits i64")
    };
    let (mut x, mut y) = (shift(x), shift(y));
    // 2. Pre-rotate into the right half-plane.
    let mut z: i64 = 0;
    if x < 0 {
        x = -x;
        y = -y;
        z = 1 << 31; // +180 degrees
    }
    // 3. Vectoring: drive y to 0, accumulating the removed angle.
    for (i, &a) in ATAN_T.iter().enumerate() {
        let (dx, dy) = (y >> i, x >> i); // arithmetic shifts (floor)
        if y > 0 {
            x += dx;
            y -= dy;
            z += a;
        } else {
            x -= dx;
            y += dy;
            z -= a;
        }
    }
    // Round half up to whole Bam, then wrap to 0..=65535.
    let bam = (z + (1 << 15)) >> 16;
    u16::try_from(bam.rem_euclid(65_536)).expect("wrapped into u16")
}

/// SPEC: canon §1.9, §21 test 46, doc 02 §4.4 `yaw_from_dir(dx, dz) =
/// atan2_bam(-dx.raw(), -dz.raw())`: the canon §1.9 yaw (0 faces -Z,
/// counter-clockwise seen from above) that faces the horizontal direction
/// `(dx, dz)`, the inverse of `fwd`.
#[inline]
#[must_use]
pub fn yaw_from_dir(dx: Fx, dz: Fx) -> Bam {
    atan2_bam(-dx.raw(), -dz.raw())
}

/// SPEC: canon §1.9, doc 02 §4.4 `pitch_from_dir(h, dy) = (atan2_bam(dy.raw(), h.raw()) as i16).clamp(-16000, 16000)`,
/// where `h >= 0` is the horizontal length and `dy` the vertical component.
#[inline]
#[must_use]
pub fn pitch_from_dir(h: Fx, dy: Fx) -> i16 {
    // `as i16` is the canon §1.9 two's-complement reinterpretation of a Bam.
    (atan2_bam(dy.raw(), h.raw()) as i16).clamp(-PITCH_LIMIT, PITCH_LIMIT)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fx::fx_from_milli;
    use crate::trig::{cos_bam, sin_bam};
    use proptest::prelude::*;

    #[test]
    fn atan_table_matches_doc() {
        assert_eq!(
            ATAN_T,
            [
                536_870_912,
                316_933_406,
                167_458_907,
                85_004_756,
                42_667_331,
                21_354_465,
                10_679_838,
                5_340_245,
                2_670_163,
                1_335_087,
                667_544,
                333_772,
                166_886,
                83_443,
                41_722,
                20_861
            ]
        );
        // atan(1) is exactly one eighth of a turn.
        assert_eq!(ATAN_T[0], 1 << 29);
        for w in ATAN_T.windows(2) {
            assert!(w[0] > w[1]);
        }
    }

    #[test]
    fn axes_and_diagonals() {
        // 0, 90, 180, 270 degrees.
        assert_eq!(atan2_bam(0, 1), 0);
        assert_eq!(atan2_bam(1, 0), 16_384);
        assert_eq!(atan2_bam(0, -1), 32_768);
        assert_eq!(atan2_bam(-1, 0), 49_152);
        assert_eq!(atan2_bam(0, 0), 0);
        assert_eq!(atan2_bam(0, i64::MIN), 32_768);
        assert_eq!(atan2_bam(i64::MAX, 0), 16_384);
        // 45-degree diagonals in every quadrant, at several magnitudes.
        for k in [1i64, 7, 1000, 1 << 20, 1 << 40, 1 << 62, i64::MAX] {
            assert_eq!(atan2_bam(k, k), 8192, "k = {k}");
            assert_eq!(atan2_bam(k, -k), 24_576, "k = {k}");
            assert_eq!(atan2_bam(-k, -k), 40_960, "k = {k}");
            assert_eq!(atan2_bam(-k, k), 57_344, "k = {k}");
        }
        assert_eq!(atan2_bam(i64::MIN, i64::MIN), 40_960);
    }

    #[test]
    fn doc_examples() {
        // Doc 02 §4.4 examples.
        assert_eq!(atan2_bam(1, 1), 8192);
        assert_eq!(atan2_bam(3, 4), 6712);
        assert_eq!(atan2_bam(4, 3), 9672);
        assert_eq!(atan2_bam(7, -24), 29_808);
        assert_eq!(atan2_bam(-5, -5), 40_960);
        assert_eq!(atan2_bam(2, -1), 21_220);
        assert_eq!(atan2_bam(1, 1_000_000), 0);
    }

    #[test]
    fn doc02_t05_atan2_values() {
        // Doc 02 acceptance test 5.
        let cases = [
            (1, 1),
            (3, 4),
            (4, 3),
            (7, -24),
            (-5, -5),
            (2, -1),
            (1, 1_000_000),
            (5, 0),
            (0, -3),
            (0, 0),
        ];
        let want = [
            8192u16, 6712, 9672, 29_808, 40_960, 21_220, 0, 16_384, 32_768, 0,
        ];
        for ((y, x), w) in cases.iter().zip(want) {
            assert_eq!(atan2_bam(*y, *x), w, "atan2_bam({y}, {x})");
        }
    }

    #[test]
    fn doc02_t06_million_random_pairs_within_one_bam() {
        // Doc 02 acceptance test 6: 1,000,000 pairs drawn as next_u64() as i64
        // from Rng::from_seed64(7), checked with integer cross products only.
        let mut rng = crate::rng::Rng::from_seed64(7);
        for _ in 0..1_000_000 {
            let y = rng.next_u64() as i64;
            let x = rng.next_u64() as i64;
            if x == 0 && y == 0 {
                continue;
            }
            let b = atan2_bam(y, x);
            assert!(within_one_bam(y, x, b), "({x}, {y}) -> {b}");
        }
    }

    /// SPEC: canon §21 test 46. `yaw_from_dir(0, -1 m)` is within 1 Bam of 0,
    /// and `yaw_from_dir(-1 m, 0)` is within 1 Bam of 16384, the yaw whose
    /// `fwd` is −X (canon §1.9: `atan2_bam(y, x)` is the angle of `(x, y)`
    /// counter-clockwise from +x, and `yaw_from_dir(dx, dz) = atan2_bam(-dx, -dz)`).
    #[test]
    fn canon_t46_yaw_from_dir() {
        let m = fx_from_milli(1000);
        let north = yaw_from_dir(Fx::ZERO, -m);
        let west = yaw_from_dir(-m, Fx::ZERO);
        assert!(crate::trig::ang_diff(north, 0) <= 1, "north -> {north}");
        assert!(crate::trig::ang_diff(west, 16_384) <= 1, "west -> {west}");
        // 16384 is the yaw whose forward vector is −X: fwd(16384, 0) = (-2^30, 0, 0).
        assert_eq!(crate::trig::fwd(16_384, 0), [-(1 << 30), 0, 0]);
        // The argument convention: atan2_bam(y, x) measures (x, y) from +x.
        assert_eq!(atan2_bam(0, 1), 0);
        assert_eq!(atan2_bam(1, 0), 16_384);
    }

    /// Review (canon §1.9, §21 test 46): the yaw that faces each cardinal and
    /// diagonal direction (yaw 0 faces −Z, counter-clockwise from above: −X
    /// is 16384, +Z 32768, +X 49152), within the ±1 Bam contract, at 1 m and
    /// at 100 km.
    #[test]
    fn canon_t46_cardinals_and_diagonals() {
        for len in [1_000i64, 100_000_000] {
            let m = fx_from_milli(len);
            let z = Fx::ZERO;
            let cases = [
                (z, -m, 0u16),
                (-m, -m, 8_192),
                (-m, z, 16_384),
                (-m, m, 24_576),
                (z, m, 32_768),
                (m, m, 40_960),
                (m, z, 49_152),
                (m, -m, 57_344),
            ];
            for (dx, dz, want) in cases {
                let got = yaw_from_dir(dx, dz);
                assert!(
                    crate::trig::ang_diff(got, want) <= 1,
                    "({len}) {want} -> {got}"
                );
            }
        }
    }

    #[test]
    fn yaw_and_pitch_examples() {
        // Doc 02 §4.4 yaw examples.
        let one = Fx::ONE;
        assert_eq!(yaw_from_dir(-one, Fx::ZERO), 16_384); // west
        assert_eq!(yaw_from_dir(Fx::ZERO, -one), 0); // north
        assert_eq!(yaw_from_dir(one, Fx::ZERO), 49_152); // east
        assert_eq!(yaw_from_dir(-one, -one), 8192); // north-west
        // Pitch: level, 45 degrees up and down, and clamped near vertical.
        assert_eq!(pitch_from_dir(one, Fx::ZERO), 0);
        assert_eq!(pitch_from_dir(one, one), 8192);
        assert_eq!(pitch_from_dir(one, -one), -8192);
        assert_eq!(pitch_from_dir(Fx::ZERO, one), 16_000);
        assert_eq!(pitch_from_dir(Fx::ZERO, -one), -16_000);
        assert_eq!(pitch_from_dir(fx_from_milli(1), Fx::from_int(100)), 16_000);
    }

    #[test]
    fn yaw_inverts_forward_vector() {
        // fwd(yaw, 0) = (-sin yaw, 0, -cos yaw); yaw_from_dir must recover yaw within 1 Bam.
        for yaw in (0u32..65_536).step_by(97) {
            let yaw = u16::try_from(yaw).unwrap();
            let dx = Fx::from_raw(i64::from(-sin_bam(yaw)) << 2);
            let dz = Fx::from_raw(i64::from(-cos_bam(yaw)) << 2);
            let back = yaw_from_dir(dx, dz);
            assert!(crate::trig::ang_diff(back, yaw) <= 1, "yaw {yaw} -> {back}");
        }
    }

    /// Integer-only accuracy check: the true direction of (x, y) lies within
    /// the closed cone between the rays at `b - 1` and `b + 1` Bam, judged by
    /// cross products against the Q2.30 table directions (whose angular error,
    /// about 1e-9 rad, is far below the 0.18 Bam slack of the doc 02 bound).
    fn within_one_bam(y: i64, x: i64, b: Bam) -> bool {
        let cross = |a: Bam| -> i128 {
            // cross(dir(a), v) = cos(a)*y - sin(a)*x; >= 0 means v is counter-clockwise of dir(a).
            i128::from(cos_bam(a)) * i128::from(y) - i128::from(sin_bam(a)) * i128::from(x)
        };
        let dot = |a: Bam| -> i128 {
            i128::from(cos_bam(a)) * i128::from(x) + i128::from(sin_bam(a)) * i128::from(y)
        };
        let lo = b.wrapping_sub(1);
        let hi = b.wrapping_add(1);
        cross(lo) >= 0 && cross(hi) <= 0 && dot(b) > 0
    }

    #[test]
    fn small_grid_within_one_bam() {
        // Doc 02 §4.4: every integer pair in -40..=40 is within the contract.
        for y in -40i64..=40 {
            for x in -40i64..=40 {
                if x == 0 && y == 0 {
                    continue;
                }
                let b = atan2_bam(y, x);
                assert!(within_one_bam(y, x, b), "({x}, {y}) -> {b}");
            }
        }
    }

    /// Signed error in Bam of `atan2_bam(y, x)` against the f64 angle (cross-check only).
    #[allow(clippy::float_arithmetic, clippy::disallowed_types)]
    fn float_error(y: i64, x: i64) -> f64 {
        let exact = (y as f64).atan2(x as f64) / core::f64::consts::TAU * 65536.0;
        let got = f64::from(atan2_bam(y, x));
        let mut e = (got - exact).rem_euclid(65536.0);
        if e > 32768.0 {
            e -= 65536.0;
        }
        e.abs()
    }

    #[test]
    #[allow(clippy::float_arithmetic, clippy::disallowed_types)]
    fn float_cross_check_error_bounds() {
        // Cross-check only (floats never define expected values). Doc 02 §4.4
        // reports at most 0.818 Bam over random inputs at magnitudes 2^10 to
        // 2^62 and at most 0.788 Bam over every integer pair in -40..=40; the
        // contract is 1 Bam. Re-measure both on a deterministic sample.
        let mut rng = crate::rng::Rng::from_seed64(0xA7A2);
        let mut worst: f64 = 0.0;
        for _ in 0..300_000 {
            let mag = 10 + rng.range(53); // 2^10 ..= 2^62
            let x = rng.range_incl(-(1i64 << mag), 1i64 << mag);
            let y = rng.range_incl(-(1i64 << mag), 1i64 << mag);
            if x == 0 && y == 0 {
                continue;
            }
            worst = worst.max(float_error(y, x));
        }
        let mut grid: f64 = 0.0;
        for y in -40i64..=40 {
            for x in -40i64..=40 {
                if x != 0 || y != 0 {
                    grid = grid.max(float_error(y, x));
                }
            }
        }
        std::println!("atan2_bam worst error: random {worst:.4} Bam, grid {grid:.4} Bam");
        assert!(worst <= 0.818 + 1e-3, "random worst error {worst} Bam");
        assert!(grid <= 0.788 + 1e-3, "grid worst error {grid} Bam");
    }

    proptest! {
        #[test]
        fn within_one_bam_random(y in any::<i64>(), x in any::<i64>()) {
            prop_assume!(x != 0 || y != 0);
            let b = atan2_bam(y, x);
            prop_assert!(within_one_bam(y, x, b), "({}, {}) -> {}", x, y, b);
        }

        #[test]
        fn within_one_bam_small_magnitudes(y in -(1i64 << 12)..(1i64 << 12), x in -(1i64 << 12)..(1i64 << 12)) {
            prop_assume!(x != 0 || y != 0);
            prop_assert!(within_one_bam(y, x, atan2_bam(y, x)));
        }

        #[test]
        fn quadrant_correct(y in 1i64..(1i64 << 50), x in 1i64..(1i64 << 50)) {
            // Strictly inside a quadrant the result lies in that quadrant,
            // widened by the 1 Bam contract at both edges (wrapping arcs).
            let in_arc = |b: Bam, start: Bam| b.wrapping_sub(start.wrapping_sub(1)) <= 16_386;
            prop_assert!(in_arc(atan2_bam(y, x), 0));
            prop_assert!(in_arc(atan2_bam(y, -x), 16_384));
            prop_assert!(in_arc(atan2_bam(-y, -x), 32_768));
            prop_assert!(in_arc(atan2_bam(-y, x), 49_152));
        }

        #[test]
        fn scale_invariant(y in -(1i64 << 20)..(1i64 << 20), x in -(1i64 << 20)..(1i64 << 20), k in 0u32..30) {
            // Inputs below 2^52 are normalized by exact left shifts, so scaling
            // by a power of two cannot change the result.
            prop_assume!(x != 0 || y != 0);
            prop_assert_eq!(atan2_bam(y << k, x << k), atan2_bam(y, x));
        }

        #[test]
        fn deterministic(y in any::<i64>(), x in any::<i64>()) {
            prop_assert_eq!(atan2_bam(y, x), atan2_bam(y, x));
        }
    }
}
